window.__PAGES=window.__PAGES||{};window.__PAGES["pages/broadcast-messages.html"]="<!-- Broadcast Pesan — table of broadcasts -->\n<div class=\"broadcast-layout\">\n  <aside class=\"broadcast-sidenav\">\n    <div class=\"sn-title\">Broadcast Massal</div>\n    <div class=\"sn-item active\" onclick=\"go('broadcast/messages')\">📢 Pesan</div>\n    <div class=\"sn-item\" onclick=\"go('broadcast/draft')\">📝 Draft</div>\n    <div class=\"sn-item\" onclick=\"go('broadcast/templates')\">📋 Template</div>\n  </aside>\n  <div class=\"broadcast-body\">\n    <div class=\"page-header\">\n      <h1>Broadcast</h1>\n      <button class=\"btn primary\" onclick=\"openBcModal()\">+ Buat Broadcast</button>\n    </div>\n    <div class=\"page-filters\" id=\"bcFilters\"></div>\n    <div class=\"page-body\">\n      <table class=\"data-table\" id=\"bcTable\">\n        <thead><tr><th>Nama</th><th>Template</th><th>Penerima</th><th>Status</th><th>Tanggal</th><th></th></tr></thead>\n        <tbody id=\"bcBody\"></tbody>\n      </table>\n    </div>\n  </div>\n</div>\n\n<!-- Modal -->\n<div class=\"modal-overlay\" id=\"bcModal\">\n  <div class=\"modal\">\n    <h3 id=\"bcModalTitle\">Buat Broadcast</h3>\n    <label>Nama Broadcast<input type=\"text\" id=\"bcName\" placeholder=\"Contoh: Promo Akhir Tahun\"></label>\n    <label>Template<select id=\"bcTpl\"></select></label>\n    <label>Jumlah Penerima<input type=\"number\" id=\"bcRecipients\" min=\"1\" value=\"100\"></label>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeBcModal()\">Batal</button>\n      <button class=\"btn primary\" onclick=\"saveBc()\">Simpan</button>\n    </div>\n  </div>\n</div>\n\n<script>\nlet bcFilter='all', bcEditId=null;\n\nfunction renderBcFilters(){\n  const el=document.getElementById('bcFilters');\n  const counts={all:DB.broadcasts.length,sent:0,scheduled:0,failed:0};\n  DB.broadcasts.forEach(b=>{if(counts[b.status]!==undefined)counts[b.status]++});\n  el.innerHTML=['all','sent','scheduled','failed'].map(s=>{\n    const label=s==='all'?'Semua':s.charAt(0).toUpperCase()+s.slice(1);\n    return `<span class=\"filter-chip ${bcFilter===s?'active':''}\" onclick=\"setBcFilter('${s}')\">${label} (${counts[s]})</span>`;\n  }).join('');\n}\n\nfunction setBcFilter(f){bcFilter=f;renderBcFilters();renderBcTable()}\n\nfunction renderBcTable(){\n  const rows=DB.broadcasts.filter(b=>bcFilter==='all'||b.status===bcFilter);\n  document.getElementById('bcBody').innerHTML=rows.map(b=>{\n    const tpl=DB.templates.find(t=>t.id===b.templateId);\n    const statusCls=b.status==='sent'?'resolved':b.status==='scheduled'?'pending':'open';\n    const date=b.sentAt?fmtDate(b.sentAt):b.scheduledAt?fmtDate(b.scheduledAt):'-';\n    return `<tr>\n      <td><b>${b.name}</b></td>\n      <td>${tpl?tpl.name:'-'}</td>\n      <td>${b.recipients.toLocaleString('id-ID')}</td>\n      <td><span class=\"status ${statusCls}\">${b.status}</span></td>\n      <td>${date}</td>\n      <td><button class=\"btn\" onclick=\"editBc('${b.id}')\" style=\"font-size:11px\">✏️</button> <button class=\"btn danger\" onclick=\"delBc('${b.id}')\" style=\"font-size:11px\">🗑</button></td>\n    </tr>`;\n  }).join('')||'<tr><td colspan=\"6\" style=\"text-align:center;color:var(--muted);padding:32px\">Belum ada broadcast</td></tr>';\n}\n\nfunction openBcModal(id){\n  bcEditId=id||null;\n  const m=document.getElementById('bcModal');\n  document.getElementById('bcModalTitle').textContent=id?'Edit Broadcast':'Buat Broadcast';\n  const sel=document.getElementById('bcTpl');\n  sel.innerHTML=DB.templates.map(t=>`<option value=\"${t.id}\">${t.name}</option>`).join('');\n  if(id){\n    const b=dbFind('broadcasts',id);\n    document.getElementById('bcName').value=b.name;\n    sel.value=b.templateId;\n    document.getElementById('bcRecipients').value=b.recipients;\n  }else{\n    document.getElementById('bcName').value='';\n    document.getElementById('bcRecipients').value=100;\n  }\n  m.classList.add('open');\n}\nfunction closeBcModal(){document.getElementById('bcModal').classList.remove('open')}\n\nfunction saveBc(){\n  const name=document.getElementById('bcName').value.trim();\n  if(!name)return showToast('Nama wajib diisi');\n  const tplId=document.getElementById('bcTpl').value;\n  const rec=parseInt(document.getElementById('bcRecipients').value)||0;\n  if(bcEditId){\n    dbUpdate('broadcasts',bcEditId,{name,templateId:tplId,recipients:rec});\n    showToast('Broadcast diperbarui');\n  }else{\n    dbAdd('broadcasts',{id:genId('bc'),name,templateId:tplId,recipients:rec,status:'scheduled',scheduledAt:new Date().toISOString()});\n    showToast('Broadcast dibuat');\n  }\n  closeBcModal();renderBcTable();renderBcFilters();\n}\n\nfunction editBc(id){openBcModal(id)}\nfunction delBc(id){dbRemove('broadcasts',id);renderBcTable();renderBcFilters();showToast('Broadcast dihapus')}\n\nrenderBcFilters();renderBcTable();\n</script>\n";
